window.CIE3=(function(){var TEMAS={"position":{"nome":"Position","nome_pt":"Posição","cor":"#f472b6","emoji":"📍"},"directions":{"nome":"Directions and maps","nome_pt":"Direções e mapas","cor":"#fb7185","emoji":"🧭"},"perspective":{"nome":"Changing perspective","nome_pt":"Mudando a perspectiva","cor":"#fbbf24","emoji":"👀"},"forces":{"nome":"Wind and water","nome_pt":"Vento e água","cor":"#38bdf8","emoji":"🌬️"},"objects":{"nome":"Movement of objects","nome_pt":"Movimento dos objetos","cor":"#a78bfa","emoji":"⚽"},"animals":{"nome":"Animals and body","nome_pt":"Animais e corpo","cor":"#34d399","emoji":"🐾"},"pushpull":{"nome":"Push or pull","nome_pt":"Empurrar ou puxar","cor":"#f97316","emoji":"💪"}};var ITENS=[{"id":"a01","tema":"position","tipo":"rapida","at":["A1"],"p":"Where is the teddy bear?","p_pt":"Onde está o ursinho de pelúcia?","o":["in the box","on the box","under the box"],"o_pt":["dentro da caixa","em cima da caixa","embaixo da caixa"],"dica":"Olhe bem: a caixa está aberta. Onde fica o corpo do ursinho?","dica_en":"Look: the box is open. Where is the bear's body?","ex":"In: a thing has something around it. The bear is in the box.","ex_pt":"In: a coisa tem algo em volta. O ursinho está dentro da caixa.","img":"media/cie3/prep-in.jpg","c":0},{"id":"a04","tema":"position","tipo":"rapida","at":["A2","A10"],"p":"Where is the apple?","p_pt":"Onde está a maçã?","o":["on the book","above the book","under the book"],"o_pt":["em cima do livro (encostada)","acima do livro (sem encostar)","embaixo do livro"],"dica":"A maçã está encostando no livro?","dica_en":"Is the apple touching the book?","ex":"On means touching the top. The apple touches the book, so it is on the book.","ex_pt":"On é encostado em cima. A maçã encosta no livro, então está on the book.","img":"media/cie3/prep-on.jpg","c":0},{"id":"a06","tema":"position","tipo":"conceito","at":["A2","A10"],"p":"The apple touches the book. The apple is ___ the book.","p_pt":"A maçã encosta no livro. A maçã está ___ o livro.","o":["on","above","below"],"o_pt":["em cima de (encostada)","acima de (sem encostar)","abaixo de"],"dica":"Qual palavra usamos quando as duas coisas se encostam?","dica_en":"Which word do we use when two things touch?","ex":"On = touching. Above = higher, not touching. The apple touches the book: on.","ex_pt":"On = encostado. Above = mais alto, sem encostar. A maçã encosta no livro: on.","c":0},{"id":"a07","tema":"position","tipo":"rapida","at":["A3"],"p":"Where is the ball?","p_pt":"Onde está a bola?","o":["under the table","on the table","above the table"],"o_pt":["embaixo da mesa","em cima da mesa","acima da mesa"],"dica":"Olhe onde a bola está: no chão ou lá no alto?","dica_en":"Look at the ball: on the floor or up high?","ex":"Under means lower, with something on top of it. The ball is under the table.","ex_pt":"Under é mais baixo, com algo por cima. A bola está embaixo da mesa.","img":"media/cie3/prep-under.jpg","c":0},{"id":"a09","tema":"position","tipo":"rapida","at":["A4"],"p":"Where is the boy?","p_pt":"Onde está o menino?","o":["behind the tree","in front of the tree","on the tree"],"o_pt":["atrás da árvore","na frente da árvore","em cima da árvore"],"dica":"A árvore esconde uma parte do menino?","dica_en":"Does the tree hide part of the boy?","ex":"Behind: the tree hides part of the boy. The boy is behind the tree.","ex_pt":"Behind: a árvore esconde parte do menino. Ele está atrás da árvore.","img":"media/cie3/prep-behind.jpg","c":0},{"id":"a12","tema":"position","tipo":"rapida","at":["A5"],"p":"Where is the dog?","p_pt":"Onde está o cachorro?","o":["in front of the chair","behind the chair","on the chair"],"o_pt":["na frente da cadeira","atrás da cadeira","em cima da cadeira"],"dica":"Alguma coisa esconde o cachorro?","dica_en":"Is anything hiding the dog?","ex":"In front of: nothing hides the dog. The dog is in front of the chair.","ex_pt":"In front of: nada esconde o cachorro. Ele está na frente da cadeira.","img":"media/cie3/prep-in-front-of.jpg","c":0},{"id":"a16","tema":"position","tipo":"rapida","at":["A6"],"p":"Where is the teddy bear?","p_pt":"Onde está o ursinho de pelúcia?","o":["between the two plants","behind the two plants","on the two plants"],"o_pt":["entre as duas plantas","atrás das duas plantas","em cima das duas plantas"],"dica":"Quantas plantas há e onde fica o ursinho?","dica_en":"How many plants are there? Where is the bear?","ex":"Between means in the middle of two things. The bear is between the plants.","ex_pt":"Between é no meio de duas coisas. O ursinho está entre as plantas.","img":"media/cie3/prep-between.jpg","c":0},{"id":"a19","tema":"position","tipo":"rapida","at":["A7"],"p":"Where is the clock?","p_pt":"Onde está o relógio?","o":["next to the lamp","on the lamp","far from the lamp"],"o_pt":["ao lado do abajur","em cima do abajur","longe do abajur"],"dica":"Veja a distância entre os dois.","dica_en":"Look at the space between them.","ex":"Next to means right at the side. The clock is next to the lamp.","ex_pt":"Next to é bem ao lado. O relógio está ao lado do abajur.","img":"media/cie3/prep-next-to.jpg","c":0},{"id":"a22","tema":"position","tipo":"rapida","at":["A8"],"p":"Where is the tree?","p_pt":"Onde está a árvore?","o":["near the house","far from the house","on the house"],"o_pt":["perto da casa","longe da casa","em cima da casa"],"dica":"Veja a distância da árvore até a casa.","dica_en":"Look at how much space is between the tree and the house.","ex":"Near means close. The tree is close to the house: near the house.","ex_pt":"Near é perto. A árvore está perto da casa.","img":"media/cie3/prep-near.jpg","c":0},{"id":"a24","tema":"position","tipo":"rapida","at":["A9"],"p":"Where is the tree?","p_pt":"Onde está a árvore?","o":["far from the house","next to the house","near the house"],"o_pt":["longe da casa","ao lado da casa","perto da casa"],"dica":"Para que serve a seta comprida na figura?","dica_en":"What does the long arrow show?","ex":"Far from means not close. The long arrow shows the tree is far from the house.","ex_pt":"Far from é longe. A seta comprida mostra que a árvore está longe da casa.","img":"media/cie3/prep-far-from.jpg","c":0},{"id":"a26","tema":"position","tipo":"conceito","at":["A8","A9"],"p":"Which one is the opposite of \"near\"?","p_pt":"Qual é o oposto de \"near\"?","o":["far from","next to","between"],"o_pt":["longe de","ao lado de","entre"],"dica":"Lembre das duas figuras da casa e da árvore.","dica_en":"Remember the two pictures of the house and the tree.","ex":"Near means close. Far from means not close. They are opposites.","ex_pt":"Near é perto. Far from é longe. São opostos.","c":0},{"id":"a28","tema":"position","tipo":"rapida","at":["A10","A2"],"p":"Where is the lamp?","p_pt":"Onde está a lâmpada?","o":["above the table","on the table","under the table"],"o_pt":["acima da mesa (sem encostar)","em cima da mesa (encostada)","embaixo da mesa"],"dica":"A lâmpada encosta na mesa?","dica_en":"Does the lamp touch the table?","ex":"Above means higher, not touching. The lamp does not touch the table: above.","ex_pt":"Above é mais alto, sem encostar. A lâmpada não encosta na mesa: acima.","img":"media/cie3/prep-above.jpg","c":0},{"id":"a30","tema":"position","tipo":"conceito","at":["A10","A2"],"p":"The lamp is higher than the table and does not touch it. The lamp is ___ the table.","p_pt":"A lâmpada está mais alta que a mesa e não encosta nela. A lâmpada está ___ a mesa.","o":["above","on","below"],"o_pt":["acima de (sem encostar)","em cima de (encostada)","abaixo de"],"dica":"Qual palavra serve quando NÃO encosta?","dica_en":"Which word do we use when things do NOT touch?","ex":"Above = higher, not touching. On = touching. The lamp does not touch: above.","ex_pt":"Above = mais alto, sem encostar. On = encostado. A lâmpada não encosta: above.","c":0},{"id":"a31","tema":"position","tipo":"rapida","at":["A11"],"p":"Where is the cat?","p_pt":"Onde está o gato?","o":["below the shelf","on the shelf","above the shelf"],"o_pt":["abaixo da prateleira","em cima da prateleira","acima da prateleira"],"dica":"O gato está mais alto ou mais baixo que a prateleira?","dica_en":"Is the cat higher or lower than the shelf?","ex":"Below means lower. The cat is lower than the shelf: below the shelf.","ex_pt":"Below é mais baixo. O gato está mais baixo que a prateleira: abaixo dela.","img":"media/cie3/prep-below.jpg","c":0},{"id":"a33","tema":"position","tipo":"conceito","at":["A3","A11"],"p":"Which two words can finish the sentence? \"The cat is ___ the shelf.\"","p_pt":"Quais duas palavras completam a frase? \"O gato está ___ a prateleira.\"","o":["under and below","on and above","in and inside"],"o_pt":["under e below","on e above","in e inside"],"dica":"As duas palavras têm de dizer que ele está mais baixo.","dica_en":"Both words must say he is lower.","ex":"Under and below both tell lower. The cat is under and below the shelf.","ex_pt":"Under e below dizem mais baixo. O gato está embaixo e abaixo da prateleira.","img":"media/cie3/prep-below.jpg","c":0},{"id":"a35","tema":"position","tipo":"rapida","at":["A12"],"p":"Where is the fish?","p_pt":"Onde está o peixe?","o":["inside the bowl","on the bowl","under the bowl"],"o_pt":["dentro do aquário","em cima do aquário","embaixo do aquário"],"dica":"Veja o que está em volta do peixe.","dica_en":"Look at what is around the fish.","ex":"Inside: the bowl is all around the fish. The fish is inside the bowl.","ex_pt":"Inside: o aquário está em volta do peixe. O peixe está dentro dele.","img":"media/cie3/prep-inside.jpg","c":0},{"id":"a37","tema":"position","tipo":"conceito","at":["A1","A12"],"p":"Which two words can finish the sentence? \"The fish is ___ the bowl.\"","p_pt":"Quais duas palavras completam a frase? \"O peixe está ___ o aquário.\"","o":["in and inside","on and inside","in and under"],"o_pt":["in e inside","on e inside","in e under"],"dica":"As duas palavras têm de valer para a figura.","dica_en":"Both words must be true for the picture.","ex":"In and inside almost mean the same: the fish is in and inside the bowl.","ex_pt":"In e inside querem dizer quase o mesmo: o peixe está dentro do aquário.","img":"media/cie3/prep-inside.jpg","c":0},{"id":"a38","tema":"position","tipo":"leitura","at":["A13","A14"],"p":"Look at the window. The bird is flying ___ the trees.","p_pt":"Olhe a janela. O pássaro está voando ___ as árvores.","o":["over","under","in"],"o_pt":["por cima de","embaixo de","dentro de"],"dica":"O pássaro encosta nas árvores? Ele está no alto?","dica_en":"Does the bird touch the trees? Is it up high?","ex":"Over means up in the air, higher than something. The bird flies over the trees.","ex_pt":"Over é pelo alto, por cima de algo. O pássaro voa por cima das árvores.","img":"media/cie3/room.jpg","c":0},{"id":"a40","tema":"position","tipo":"conceito","at":["A13","A10","A2"],"p":"Which two words tell that a thing is higher and NOT touching?","p_pt":"Quais duas palavras dizem que uma coisa está mais alta e SEM encostar?","o":["above and over","on and above","on and over"],"o_pt":["above e over","on e above","on e over"],"dica":"Uma destas palavras sempre encosta. Ela fica de fora.","dica_en":"One of these words always touches. Leave it out.","ex":"Above and over do not touch. On touches.","ex_pt":"Above e over não encostam. On encosta.","c":0},{"id":"a41","tema":"position","tipo":"leitura","at":["A14","A1"],"p":"Look at the table. Where is the pizza?","p_pt":"Olhe a mesa. Onde está a pizza?","o":["in the box","under the box","next to the box"],"o_pt":["dentro da caixa","embaixo da caixa","ao lado da caixa"],"dica":"Procure a caixa aberta em cima da mesa.","dica_en":"Find the open box on the table.","ex":"The box is open and the pizza is in it: in the box.","ex_pt":"A caixa está aberta e a pizza está dentro dela: in the box.","img":"media/cie3/room.jpg","c":0},{"id":"a42","tema":"position","tipo":"leitura","at":["A14","A6"],"p":"There is a guitar ___ the lamp and the plant.","p_pt":"Há um violão ___ o abajur e a planta.","o":["between","on","under"],"o_pt":["entre","em cima de","embaixo de"],"dica":"Olhe de um lado e do outro do violão.","dica_en":"Look at both sides of the guitar.","ex":"The lamp is on one side, the plant on the other: between.","ex_pt":"O abajur está de um lado, a planta do outro: entre.","img":"media/cie3/room.jpg","c":0},{"id":"a43","tema":"position","tipo":"leitura","at":["A14","A5"],"p":"Where are the two dogs?","p_pt":"Onde estão os dois cachorros?","o":["under the table","behind the table","on the table"],"o_pt":["debaixo da mesa","atrás da mesa","em cima da mesa"],"dica":"Olhe embaixo do tampo da mesa.","dica_en":"Look below the table top.","ex":"The dogs are under the table, below the top, between its legs.","ex_pt":"Os cachorros estão debaixo da mesa, entre as pernas dela.","img":"media/cie3/room.jpg","c":0},{"id":"a47","tema":"position","tipo":"leitura","at":["A14","A5"],"p":"The rug is ___ the sofa.","p_pt":"O tapete está ___ o sofá.","o":["in front of","behind","far from"],"o_pt":["na frente de","atrás de","longe de"],"dica":"Quem está mais perto de você: o tapete ou o sofá?","dica_en":"Which is closer to you: the rug or the sofa?","ex":"The rug is closer to us than the sofa: it is in front of the sofa.","ex_pt":"O tapete está mais perto de nós que o sofá: está na frente dele.","img":"media/cie3/room.jpg","c":0},{"id":"d01","tema":"directions","tipo":"leitura","at":["D1","D6"],"p":"Look at the map. Which section is on the left of the Auditorium?","p_pt":"Olhe o mapa. Qual seção está à esquerda do Auditório?","o":["A section","B section","C section"],"o_pt":["Seção A","Seção B","Seção C"],"dica":"Lado de quem olha o mapa: qual é a sua mão esquerda?","dica_en":"Use your side as you look at the map. Which is your left hand?","ex":"Left is your left hand's side of the map. A section is left of the Auditorium.","ex_pt":"Esquerda é o lado da sua mão esquerda. A seção A está à esquerda do Auditório.","img":"media/cie3/map-school.jpg","c":0},{"id":"d02","tema":"directions","tipo":"leitura","at":["D1","D6"],"p":"The B section is on the ___ of the Auditorium.","p_pt":"A seção B está à ___ do Auditório.","o":["right","left","top"],"o_pt":["direita","esquerda","parte de cima"],"dica":"Primeiro ache o Auditório, depois a seção B.","dica_en":"First find the Auditorium, then find B section.","ex":"B section is on your right hand's side of the Auditorium: right.","ex_pt":"A seção B fica do lado da sua mão direita: direita.","img":"media/cie3/map-school.jpg","c":0},{"id":"d03","tema":"directions","tipo":"leitura","at":["D1","D6"],"p":"What is between the A section and the B section?","p_pt":"O que está entre a seção A e a seção B?","o":["the Auditorium","the Trix","the Entrance"],"o_pt":["o Auditório","a Trix","a Entrada"],"dica":"Coloque um dedo em cada seção e olhe o meio.","dica_en":"Put one finger on each section and look at the middle.","ex":"The Auditorium has A on one side and B on the other: it is between.","ex_pt":"O Auditório tem a seção A de um lado e a B do outro: está entre elas.","img":"media/cie3/map-school.jpg","c":0},{"id":"d09","tema":"directions","tipo":"leitura","at":["D1","D6"],"p":"Where is the Entrance?","p_pt":"Onde está a Entrada?","o":["under the Auditorium","above the C section","next to the Treehouse"],"o_pt":["embaixo do Auditório","acima da seção C","ao lado da Casa na Árvore"],"dica":"Ache a palavra Entrance. Ela está na parte alta ou baixa do mapa?","dica_en":"Find the word Entrance. Is it high or low on the map?","ex":"The Entrance is low on the map, under the Auditorium.","ex_pt":"A Entrada fica na parte baixa do mapa, embaixo do Auditório.","img":"media/cie3/map-school.jpg","c":0},{"id":"d13","tema":"directions","tipo":"leitura","at":["D5"],"p":"The red pin marks a place on this map. Which place?","p_pt":"O pino vermelho marca um lugar neste mapa. Qual lugar?","o":["a Year 2 classroom","the Auditorium","the Entrance"],"o_pt":["uma sala do Year 2","o Auditório","a Entrada"],"dica":"Procure o pino vermelho e leia o que está embaixo dele.","dica_en":"Find the red pin and read the words under it.","ex":"A red pin marks a place. Here it marks a Year 2 classroom.","ex_pt":"O pino vermelho marca um lugar. Aqui ele marca uma sala do Year 2.","img":"media/cie3/map-school.jpg","c":0},{"id":"d15","tema":"directions","tipo":"conceito","at":["D5"],"p":"What does a red pin do on a map?","p_pt":"O que um pino vermelho faz num mapa?","o":["It marks a place.","It shows the way to go.","It is a kind of map."],"o_pt":["Ele marca um lugar.","Ele mostra o caminho a seguir.","Ele e um tipo de mapa."],"dica":"Lembre do pino no mapa da escola.","dica_en":"Remember the pin on the school map.","ex":"A red pin marks a place on the map.","ex_pt":"Um pino vermelho marca um lugar no mapa.","c":0},{"id":"d16","tema":"directions","tipo":"rapida","at":["D4"],"p":"What kind of map is this?","p_pt":"Que tipo de mapa é este?","o":["a map of the school","a map of a city","a GPS route"],"o_pt":["um mapa da escola","um mapa de uma cidade","uma rota de GPS"],"dica":"Leia as palavras: que lugares aparecem nele?","dica_en":"Read the words: what places are on it?","ex":"It shows classrooms, gyms and the Auditorium, so it is a map of the school.","ex_pt":"Mostra salas, ginásios e o Auditório, então é um mapa da escola.","img":"media/cie3/map-school.jpg","c":0},{"id":"d19","tema":"directions","tipo":"conceito","at":["D4","D5"],"p":"Which two are kinds of maps?","p_pt":"Quais dois são tipos de mapa?","o":["a city map and a GPS route","a red pin and a city map","a red pin and a GPS route"],"o_pt":["um mapa de cidade e uma rota de GPS","um pino vermelho e um mapa de cidade","um pino vermelho e uma rota de GPS"],"dica":"Uma destas coisas só marca um lugar: não é mapa.","dica_en":"One of these only marks a place: it is not a map.","ex":"City maps and GPS routes are maps. A red pin only marks a place.","ex_pt":"Mapa de cidade e rota de GPS são mapas. O pino só marca um lugar.","c":0},{"id":"d20","tema":"directions","tipo":"conceito","at":["D2"],"p":"When we read maps, we need to pay a lot of attention to...","p_pt":"Quando lemos mapas, precisamos prestar muita atencao em...","o":["the details and the path","the red pin and the colours","the left and the right"],"o_pt":["os detalhes e o caminho","o pino vermelho e as cores","a esquerda e a direita"],"dica":"Lembre da frase em destaque no slide Reading Map.","dica_en":"Remember the big sentence on the Reading Map slide.","ex":"Map rule: pay attention to the details and the path.","ex_pt":"Regra do mapa: atencao aos detalhes e ao caminho.","c":0},{"id":"d21","tema":"directions","tipo":"conceito","at":["D2"],"p":"On a map, the path is…","p_pt":"Em um mapa, o caminho (path) é…","o":["the way we are going","the pin on the map","the name of a place"],"o_pt":["o caminho por onde vamos","o pino no mapa","o nome de um lugar"],"dica":"Lembre: path (way).","dica_en":"Remember: path (way).","ex":"Path means way: it is the way we are going.","ex_pt":"Path quer dizer way: é o caminho por onde vamos.","c":0},{"id":"d22","tema":"directions","tipo":"rapida","at":["D3"],"p":"We might get ___ if we run or don't pay attention.","p_pt":"Podemos ficar ___ se corrermos ou não prestarmos atenção.","o":["lost","late","tired"],"o_pt":["perdidos","atrasados","cansados"],"dica":"O que acontece quando não sabemos mais onde estamos?","dica_en":"What happens when we don't know where we are?","ex":"If we run or don't pay attention to the map, we might get lost.","ex_pt":"Se corremos ou não prestamos atenção no mapa, podemos nos perder.","c":0},{"id":"p01","tema":"perspective","tipo":"rapida","at":["P2"],"p":"This tower is seen from the...","p_pt":"Esta torre é vista de...","o":["front","top","bottom"],"o_pt":["frente","cima","baixo"],"dica":"Onde está quem tirou a foto: no gramado, olhando reto?","dica_en":"Where is the person with the camera: on the grass, looking straight?","ex":"From the front, you stand on the ground and look straight. This photo shows that.","ex_pt":"De frente, você fica no chão e olha reto. A foto mostra isso.","img":"media/cie3/view-front.jpg","c":0},{"id":"p02","tema":"perspective","tipo":"rapida","at":["P2"],"p":"This tower is seen from the...","p_pt":"Esta torre e vista de...","o":["top","front","bottom"],"o_pt":["cima (top)","frente (front)","baixo (bottom)"],"dica":"Você vê o céu ou o chão nesta foto?","dica_en":"Do you see the sky or the ground in this photo?","ex":"From the top, you look down and see the ground.","ex_pt":"De cima, voce olha para baixo e ve o chao.","img":"media/cie3/view-top.jpg","c":0},{"id":"p04","tema":"perspective","tipo":"rapida","at":["P2"],"p":"This tower is seen from the...","p_pt":"Esta torre é vista de...","o":["bottom","top","side"],"o_pt":["baixo","cima","lado"],"dica":"A ponta da torre está longe, lá no céu?","dica_en":"Is the tip of the tower far away, up in the sky?","ex":"From the bottom, you look up and the tip is far away.","ex_pt":"De baixo, você olha para cima e a ponta fica longe.","img":"media/cie3/view-bottom.jpg","c":0},{"id":"p08","tema":"perspective","tipo":"leitura","at":["P2"],"p":"You can see the whole tower and the river near it. You see it from the...","p_pt":"Voce ve a torre inteira e o rio perto dela. Voce a ve de...","o":["side","bottom","front"],"o_pt":["lado (side)","baixo (bottom)","frente (front)"],"dica":"Compare com as outras fotos da torre: dá para ver a torre inteira?","dica_en":"Compare with the other tower photos: can you see the whole tower?","ex":"The side view shows the whole tower and the river near it.","ex_pt":"A vista lateral mostra a torre inteira e o rio perto.","img":"media/cie3/view-side.jpg","c":0},{"id":"p09","tema":"perspective","tipo":"conceito","at":["P1"],"p":"Complete: Our perspective changes depending on ___ we are looking from.","p_pt":"Complete: Nossa perspectiva muda dependendo de ___ estamos olhando.","o":["where","when","why"],"o_pt":["onde","quando","por que"],"dica":"Pense em lugar, não em tempo.","dica_en":"Think about a place, not a time.","ex":"Perspective changes depending on WHERE we look from: top, bottom, front or side.","ex_pt":"A perspectiva muda conforme ONDE olhamos: de cima, de baixo, de frente ou de lado.","c":0},{"id":"p12","tema":"perspective","tipo":"rapida","at":["P3"],"p":"One object makes these three shadows. What shapes are they?","p_pt":"Um objeto faz estas três sombras. Que formas elas têm?","o":["triangle, rectangle, circle","triangle, square, rectangle","circle, square, triangle"],"o_pt":["triângulo, retângulo, círculo","triângulo, quadrado, retângulo","círculo, quadrado, triângulo"],"dica":"Olhe cada parede e o chão, um de cada vez.","dica_en":"Look at each wall and at the floor, one at a time.","ex":"One object, three shadows: a triangle, a rectangle and a circle.","ex_pt":"Um objeto, três sombras: um triângulo, um retângulo e um círculo.","img":"media/cie3/view-shadow.jpg","c":0},{"id":"p16","tema":"perspective","tipo":"conceito","at":["P3"],"p":"There is one object, but there are three different shadows. Why?","p_pt":"Ha um objeto, mas tres sombras diferentes. Por que?","o":["Each side of it is different.","The shadows are different colours.","The walls are different sizes."],"o_pt":["Cada lado dele e diferente.","As sombras tem cores diferentes.","As paredes tem tamanhos diferentes."],"dica":"Olhe o objeto: quantos ele é? Ele se mexeu?","dica_en":"Look at the object: how many are there? Did it move?","ex":"Each side of the object gives another shape.","ex_pt":"Cada lado do objeto da outra forma.","img":"media/cie3/view-shadow.jpg","c":0},{"id":"p17","tema":"perspective","tipo":"conceito","at":["P4"],"p":"Complete: People are not right or wrong. They just have a different ___ of things.","p_pt":"Complete: As pessoas não estão certas nem erradas. Elas só têm uma ___ diferente das coisas.","o":["view","shape","colour"],"o_pt":["visão","forma","cor"],"dica":"É a palavra da frase da girafa, ligada a olhar.","dica_en":"It is the word from the giraffe sentence, about looking.","ex":"The giraffe sentence says people just have a different view of things.","ex_pt":"A frase da girafa diz que as pessoas só têm uma visão diferente das coisas.","c":0},{"id":"p18","tema":"perspective","tipo":"leitura","at":["P1","P4"],"p":"The giraffe's head is up high. The woman is down low. Why do they see things differently?","p_pt":"A cabeça da girafa está lá no alto. A mulher está mais embaixo. Por que elas veem as coisas de um jeito diferente?","o":["They look from different positions.","The giraffe is right about it.","The woman is right about it."],"o_pt":["Elas olham de posições diferentes.","A girafa está certa.","A mulher está certa."],"dica":"Leia a frase no alto da figura.","dica_en":"Read the sentence at the top of the picture.","ex":"Nobody is wrong here. They look from different positions, so they have different views.","ex_pt":"Ninguém está errado. Elas olham de posições diferentes, por isso têm visões diferentes.","img":"media/cie3/view-giraffe.jpg","c":0},{"id":"n01","tema":"forces","tipo":"conceito","at":["N1"],"p":"Complete: Wind and water are two ___ forces.","p_pt":"Complete: O vento e a água são duas forças ___.","o":["natural","pushing","pulling"],"o_pt":["naturais","de empurrar","de puxar"],"dica":"Elas existem na natureza.","dica_en":"They exist in nature.","ex":"Wind and water exist in nature, so they are natural forces.","ex_pt":"O vento e a água existem na natureza, então são forças naturais.","c":0},{"id":"n02","tema":"forces","tipo":"conceito","at":["N1"],"p":"Which sentence is true about wind and water?","p_pt":"Qual frase é verdadeira sobre vento e água?","o":["Wind and water can both help us and harm us.","Wind can help us, but water can only harm us.","Water can help us, but wind can only harm us."],"o_pt":["Vento e água podem nos ajudar e nos prejudicar.","O vento pode ajudar, mas a água só prejudica.","A água pode ajudar, mas o vento só prejudica."],"dica":"Lembre das duas colunas do slide.","dica_en":"Remember the two columns on the slide.","ex":"Wind and water can be helpful and harmful.","ex_pt":"Vento e água podem ser úteis e prejudiciais.","c":0},{"id":"n07","tema":"forces","tipo":"rapida","at":["N3"],"p":"What is this? Helpful or harmful?","p_pt":"O que é isto? Útil ou perigoso?","o":["harmful: a tsunami","harmful: a flood","helpful: makes energy"],"o_pt":["perigoso: um tsunami","perigoso: uma enchente","útil: faz energia"],"dica":"Olhe o tamanho da onda chegando às casas.","dica_en":"Look at the size of the wave coming to the houses.","ex":"A tsunami is a giant wave of water. It is harmful.","ex_pt":"O tsunami é uma onda gigante de água. Ele é perigoso.","img":"media/cie3/harm-tsunami.jpg","c":0},{"id":"n08","tema":"forces","tipo":"rapida","at":["N3"],"p":"What is this? Helpful or harmful?","p_pt":"O que é isto? Útil ou perigoso?","o":["harmful: a flood","harmful: a tsunami","helpful: waters plants"],"o_pt":["perigoso: uma enchente","perigoso: um tsunami","útil: rega as plantas"],"dica":"Olhe a chuva e os carros na água. Há uma onda gigante?","dica_en":"Look at the rain and the cars in the water. Is there a giant wave?","ex":"Heavy rain can make floods. The water covers streets and cars. It is harmful.","ex_pt":"Chuva forte pode causar enchentes. A água cobre ruas e carros. É perigoso.","img":"media/cie3/harm-floods.jpg","c":0},{"id":"n09","tema":"forces","tipo":"rapida","at":["N3"],"p":"What is this? Helpful or harmful?","p_pt":"O que é isto? Útil ou prejudicial?","o":["harmful: a tornado","harmful: a tsunami","harmful: a flood"],"o_pt":["prejudicial: um tornado","prejudicial: um tsunami","prejudicial: uma enchente"],"dica":"Olhe a forma do vento no meio da figura.","dica_en":"Look at the shape of the wind in the middle of the picture.","ex":"A tornado is wind that spins in a tall funnel. It is harmful.","ex_pt":"Tornado é vento girando num funil alto. É prejudicial.","img":"media/cie3/harm-tornado.jpg","c":0},{"id":"n10","tema":"forces","tipo":"rapida","at":["N3"],"p":"What is this? Helpful or harmful?","p_pt":"O que é isto? Útil ou perigoso?","o":["harmful: strong winds","harmful: a tornado","helpful: spreads seeds"],"o_pt":["perigoso: ventos fortes","perigoso: um tornado","útil: espalha sementes"],"dica":"Há um funil no céu ou só as árvores se dobrando?","dica_en":"Is there a funnel in the sky, or only trees bending?","ex":"These strong winds bend the trees and blow the leaves. They are harmful.","ex_pt":"Estes ventos fortes dobram as árvores e levam as folhas. São perigosos.","img":"media/cie3/harm-winds.jpg","c":0},{"id":"n11","tema":"forces","tipo":"rapida","at":["N2"],"p":"What is this? Helpful or harmful?","p_pt":"O que é isto? Útil ou perigoso?","o":["helpful: waters the plants","helpful: makes energy","harmful: heavy rain"],"o_pt":["útil: rega as plantas","útil: faz energia","perigoso: chuva forte"],"dica":"Olhe de onde a água está saindo.","dica_en":"Look at where the water is coming from.","ex":"Watering the plants is on the helpful list. Water helps plants live.","ex_pt":"Regar as plantas está na lista dos úteis. A água ajuda as plantas a viver.","img":"media/cie3/help-water-plants.jpg","c":0},{"id":"n12","tema":"forces","tipo":"rapida","at":["N2","N7"],"p":"What is this? Helpful or harmful?","p_pt":"O que é isto? Útil ou perigoso?","o":["helpful: makes energy","helpful: waters plants","harmful: a flood"],"o_pt":["útil: faz energia","útil: rega as plantas","perigoso: uma enchente"],"dica":"É uma represa. Para que ela serve?","dica_en":"It is a dam. What is it for?","ex":"A dam uses moving water to make energy. It is helpful.","ex_pt":"A represa usa a água em movimento para fazer energia. É útil.","img":"media/cie3/help-water-energy.jpg","c":0},{"id":"n13","tema":"forces","tipo":"rapida","at":["N2","N7"],"p":"Which natural force turns these blades?","p_pt":"Qual força natural gira estas pás?","o":["wind","water","wind and water"],"o_pt":["vento","água","vento e água"],"dica":"Lembre da coluna helpful do slide.","dica_en":"Remember the helpful column on the slide.","ex":"Wind turns the blades of a turbine. Wind is the force here.","ex_pt":"O vento gira as pás da turbina. A força aqui é o vento.","img":"media/cie3/help-wind-energy.jpg","c":0},{"id":"n14","tema":"forces","tipo":"rapida","at":["N2","N7"],"p":"Which natural force spreads these seeds?","p_pt":"Qual força natural espalha estas sementes?","o":["wind","water","wind and water"],"o_pt":["vento","água","vento e água"],"dica":"As sementes estão no ar ou na água?","dica_en":"Are the seeds in the air or in water?","ex":"The seeds float in the air. Wind spreads the seeds, and that is helpful.","ex_pt":"As sementes flutuam no ar. O vento espalha as sementes, e isso é útil.","img":"media/cie3/help-wind-seeds.jpg","c":0},{"id":"n16","tema":"forces","tipo":"rapida","at":["N3"],"p":"Which natural force is this?","p_pt":"Qual força natural é esta?","o":["water","wind","wind and water"],"o_pt":["água","vento","vento e água"],"dica":"Do que é feita esta onda?","dica_en":"What is this wave made of?","ex":"A tsunami is a giant wave. So it is the force of water.","ex_pt":"O tsunami é uma onda gigante. Então é a força da água.","img":"media/cie3/harm-tsunami.jpg","c":0},{"id":"n19","tema":"forces","tipo":"conceito","at":["N4"],"p":"Complete: Wind is ___ in motion.","p_pt":"Complete: O vento é ___ em movimento.","o":["air","water","sand"],"o_pt":["ar","água","areia"],"dica":"É o que você respira.","dica_en":"It is what you breathe.","ex":"Wind is air in motion. Moving air is wind.","ex_pt":"O vento é ar em movimento. Ar que se move é vento.","c":0},{"id":"n23","tema":"forces","tipo":"conceito","at":["N5"],"p":"Wind moves sand. What can it make?","p_pt":"O vento move a areia. O que ele pode fazer?","o":["dunes","canyons","valleys"],"o_pt":["dunas","cânions","vales"],"dica":"Pense em montes de areia.","dica_en":"Think about hills of sand.","ex":"Wind moves sand and makes dunes. Water makes valleys and canyons.","ex_pt":"O vento move a areia e faz dunas. A água faz vales e cânions.","c":0},{"id":"n25","tema":"forces","tipo":"conceito","at":["N6"],"p":"Complete: Water is always ___.","p_pt":"Complete: A água está sempre ___.","o":["moving","helpful","harmful"],"o_pt":["em movimento","útil","perigosa"],"dica":"Pense nos rios e na chuva.","dica_en":"Think about rivers and rain.","ex":"Water is always moving. It can be helpful or harmful.","ex_pt":"A água está sempre em movimento. Ela pode ser útil ou perigosa.","c":0},{"id":"n35","tema":"forces","tipo":"conceito","at":["N8"],"p":"We need to protect our...","p_pt":"Precisamos proteger nosso(a)...","o":["air and water","only air","only water"],"o_pt":["ar e água","só o ar","só a água"],"dica":"Lembre das duas forças da lição.","dica_en":"Remember the two forces in the lesson.","ex":"Wind is moving air. We protect both air and water.","ex_pt":"Vento é ar em movimento. Protegemos ar e água.","c":0},{"id":"o01","tema":"objects","tipo":"rapida","at":["O1"],"p":"How does it move?","p_pt":"Como isso se move?","o":["It bounces.","It swings.","It slides."],"o_pt":["Quica.","Balança.","Desliza."],"dica":"Siga as linhas embaixo da bola: elas mostram o caminho.","dica_en":"Follow the lines under the ball. They show its path.","ex":"To bounce is to go up and down after hitting a surface. This ball bounces.","ex_pt":"Quicar é subir e descer depois de bater numa superfície. Esta bola quica.","img":"media/cie3/obj-bounce-soccer-ball.jpg","c":0},{"id":"o06","tema":"objects","tipo":"rapida","at":["O2"],"p":"How does it move?","p_pt":"Como isso se move?","o":["It flies.","It rolls.","It bounces."],"o_pt":["Voa.","Rola.","Quica."],"dica":"A pipa está no chão ou no céu?","dica_en":"Is the kite on the ground or in the sky?","ex":"To fly is to move through the air. The kite is in the air, so it flies.","ex_pt":"Voar é se mover pelo ar. A pipa está no ar, então voa.","img":"media/cie3/obj-fly-kite.jpg","c":0},{"id":"o08","tema":"objects","tipo":"rapida","at":["O3"],"p":"How does it move?","p_pt":"Como isso se move?","o":["It rolls.","It swings.","It flies."],"o_pt":["Rola.","Balança.","Voa."],"dica":"A lata está deitada. As linhas mostram que ela vai virando.","dica_en":"The can is on its side. The lines show it is turning.","ex":"The can lies on its side and moves by turning over and over. It rolls.","ex_pt":"A lata fica deitada e se move virando e virando. Ela rola.","img":"media/cie3/obj-roll-can.jpg","c":0},{"id":"o11","tema":"objects","tipo":"rapida","at":["O4"],"p":"How does it move?","p_pt":"Como isso se move?","o":["It slides.","It rolls.","It swings."],"o_pt":["Desliza.","Rola.","Balança."],"dica":"O cubo de gelo continua em pé, sem virar. A seta mostra o caminho.","dica_en":"The ice cube stays the same way up. The arrow shows the path.","ex":"To slide is to move smoothly along a surface. The ice cube slides.","ex_pt":"Deslizar é se mover suave sobre uma superfície. O cubo de gelo desliza.","img":"media/cie3/obj-slide-ice-cube.jpg","c":0},{"id":"o15","tema":"objects","tipo":"rapida","at":["O5"],"p":"How does it move?","p_pt":"Como isso se move?","o":["It spins.","It swings.","It flies."],"o_pt":["Gira.","Balança.","Voa."],"dica":"Veja a seta em volta do pião.","dica_en":"See the arrow around the top.","ex":"To spin is to turn around and around. The top spins.","ex_pt":"Girar é dar voltas e voltas. O pião gira.","img":"media/cie3/obj-spin-top.jpg","c":0},{"id":"o18","tema":"objects","tipo":"rapida","at":["O6"],"p":"How does it move?","p_pt":"Como ela se move?","o":["It swings.","It spins.","It slides."],"o_pt":["Ela balança (abre e fecha).","Ela gira.","Ela desliza."],"dica":"A porta abre e fecha: vai e volta.","dica_en":"The door opens and closes: it goes and comes back.","ex":"The door moves back and forth. So the door swings.","ex_pt":"A porta vai e volta. Então ela balança.","img":"media/cie3/obj-swing-door.jpg","c":0},{"id":"o19","tema":"objects","tipo":"conceito","at":["O1"],"p":"To ___ means to go up and down after hitting a surface.","p_pt":"___ significa subir e descer depois de bater numa superfície.","o":["bounce","fly","slide"],"o_pt":["quicar","voar","deslizar"],"dica":"Pense na bola de basquete.","dica_en":"Think about a basketball.","ex":"To bounce means to go up and down after hitting a surface, like a basketball.","ex_pt":"Quicar é subir e descer depois de bater numa superfície, como a bola de basquete.","c":0},{"id":"o20","tema":"objects","tipo":"conceito","at":["O2"],"p":"To ___ means to move through the air.","p_pt":"___ significa se mover pelo ar.","o":["fly","slide","roll"],"o_pt":["voar","deslizar","rolar"],"dica":"Pense no avião e na pipa.","dica_en":"Think about an airplane and a kite.","ex":"To fly means to move through the air, like an airplane.","ex_pt":"Voar é se mover pelo ar, como o avião.","c":0},{"id":"o21","tema":"objects","tipo":"conceito","at":["O3"],"p":"To ___ means to move by turning over and over.","p_pt":"___ significa se mover virando e virando.","o":["roll","spin","swing"],"o_pt":["rolar","girar","balançar"],"dica":"Pense na roda indo pela rua, de um lugar para outro.","dica_en":"Think about a wheel going along the road, from one place to another.","ex":"To roll means to move by turning over and over, like a wheel.","ex_pt":"Rolar é se mover virando e virando, como a roda.","c":0},{"id":"o22","tema":"objects","tipo":"conceito","at":["O4"],"p":"To ___ means to move smoothly along a surface.","p_pt":"___ significa se mover suave sobre uma superfície.","o":["slide","roll","swing"],"o_pt":["deslizar","rolar","balançar"],"dica":"Pense no cubo de gelo.","dica_en":"Think about an ice cube.","ex":"To slide means to move smoothly along a surface, like an ice cube.","ex_pt":"Deslizar é se mover suave sobre uma superfície, como o cubo de gelo.","c":0},{"id":"o23","tema":"objects","tipo":"conceito","at":["O5"],"p":"To ___ means to turn around and around.","p_pt":"___ significa dar voltas e voltas.","o":["spin","roll","swing"],"o_pt":["girar","rolar","balançar"],"dica":"Pense no pião.","dica_en":"Think about a top.","ex":"To spin means to turn around and around, like a top.","ex_pt":"Girar é dar voltas e voltas, como o pião.","c":0},{"id":"o24","tema":"objects","tipo":"conceito","at":["O6"],"p":"To ___ means to move back and forth like a pendulum.","p_pt":"___ significa ir e voltar como um pêndulo.","o":["swing","spin","bounce"],"o_pt":["balançar","girar","quicar"],"dica":"Pense no brinquedo do parquinho que vai e volta.","dica_en":"Think about the park toy that goes and comes back.","ex":"To swing means to move back and forth like a pendulum, like a door.","ex_pt":"Balançar é ir e voltar como um pêndulo, como a porta.","c":0},{"id":"o30","tema":"objects","tipo":"leitura","at":["O5","O3"],"p":"It turns around and around. It stays in one place. What does it do?","p_pt":"Dá voltas e voltas. Fica no mesmo lugar. O que ele faz?","o":["It spins.","It rolls.","It slides."],"o_pt":["Gira.","Rola.","Desliza."],"dica":"Se sai do lugar é uma palavra; se fica no lugar é outra.","dica_en":"If it leaves its place, it is one word. If it stays, it is another.","ex":"To spin is to turn around and around. A spinning thing stays in one place.","ex_pt":"Girar é dar voltas e voltas. O que gira fica no mesmo lugar.","c":0},{"id":"o31","tema":"objects","tipo":"leitura","at":["O3","O5"],"p":"It turns over and over. It goes to a new place. What does it do?","p_pt":"Vira e vira. Vai para um lugar novo. O que ele faz?","o":["It rolls.","It spins.","It swings."],"o_pt":["Rola.","Gira.","Balança."],"dica":"Pense na roda que vai embora pela rua.","dica_en":"Think about a wheel going away along the road.","ex":"To roll is to move by turning over and over. A rolling thing goes to a new place.","ex_pt":"Rolar é se mover virando e virando. O que rola vai para um lugar novo.","c":0},{"id":"o37","tema":"objects","tipo":"conceito","at":["O7"],"p":"Up and down, back and forth, round and round. These words tell us the…","p_pt":"Para cima e para baixo, para frente e para trás, em voltas. Essas palavras dizem a…","o":["direction","speed","surface"],"o_pt":["direção","velocidade","superfície"],"dica":"Eles dizem PARA ONDE a coisa vai.","dica_en":"They tell WHERE the thing goes.","ex":"Things move in different directions: back and forth, up and down, round and round.","ex_pt":"As coisas se movem em direções diferentes: frente e trás, cima e baixo, voltas e voltas.","c":0},{"id":"o38","tema":"objects","tipo":"conceito","at":["O8"],"p":"Things can move at different speeds. They can move…","p_pt":"As coisas podem se mover em velocidades diferentes. Elas podem se mover…","o":["slow or fast","up and down","back and forth"],"o_pt":["devagar ou rápido","para cima e para baixo","para frente e para trás"],"dica":"Velocidade diz se a coisa demora ou não.","dica_en":"Speed tells if the thing takes a long time or not.","ex":"Speed is how quickly a thing moves. Things can move slow or fast.","ex_pt":"Velocidade é a rapidez com que algo se move. As coisas podem ir devagar ou rápido.","c":0},{"id":"m01","tema":"animals","tipo":"rapida","at":["M3"],"p":"How does a fish move?","p_pt":"Como um peixe se move?","o":["It swims.","It climbs.","It walks."],"o_pt":["Nada.","Escala.","Anda."],"dica":"Pense onde o peixe vive.","dica_en":"Think about where a fish lives.","ex":"A fish lives in the water and moves by swimming. A fish swims.","ex_pt":"O peixe vive na água e se move nadando. O peixe nada.","c":0},{"id":"m02","tema":"animals","tipo":"rapida","at":["M3"],"p":"Which animal flies?","p_pt":"Qual animal voa?","o":["a bird","a fish","a frog"],"o_pt":["um pássaro","um peixe","um sapo"],"dica":"To fly é se mover pelo ar. Qual tem asas?","dica_en":"To fly is to move through the air. Which one has wings?","ex":"To fly is to move through the air. A bird flies.","ex_pt":"Voar é se mover pelo ar. O pássaro voa.","c":0},{"id":"m03","tema":"animals","tipo":"rapida","at":["M3"],"p":"A monkey goes up a tree. How does it move?","p_pt":"Um macaco sobe numa árvore. Como ele se move?","o":["It climbs.","It flies.","It crawls."],"o_pt":["Escala.","Voa.","Rasteja."],"dica":"Ele usa as mãos e os pés para subir.","dica_en":"It uses its hands and feet to go up.","ex":"A monkey goes up a tree with its hands and feet. It climbs.","ex_pt":"O macaco sobe na árvore com as mãos e os pés. Ele escala.","c":0},{"id":"m05","tema":"animals","tipo":"rapida","at":["M3"],"p":"Which animal jumps?","p_pt":"Qual animal pula?","o":["a kangaroo","a snake","a bird"],"o_pt":["um canguru","uma cobra","um pássaro"],"dica":"Qual tem pernas de trás bem fortes?","dica_en":"Which one has very strong back legs?","ex":"A kangaroo moves by jumping with strong back legs.","ex_pt":"O canguru pula com as fortes pernas de trás.","c":0},{"id":"m14","tema":"animals","tipo":"rapida","at":["M1"],"p":"Body movements: swim, climb, play, walk, sit and…","p_pt":"Movimentos do corpo: nadar, escalar, brincar, andar, sentar e…","o":["pick","write","grab"],"o_pt":["colher","escrever","agarrar"],"dica":"Write e grab estão na lista da mão? Lembre as duas listas.","dica_en":"Are write and grab on the hand list? Remember both lists.","ex":"Body list: swim, climb, play, walk, pick, sit. Pick is on it.","ex_pt":"Lista do corpo: nadar, escalar, brincar, andar, colher, sentar. Colher está nela.","c":0},{"id":"m20","tema":"animals","tipo":"rapida","at":["M2"],"p":"Which one is on the list of hand movements?","p_pt":"Qual está na lista de movimentos da mão?","o":["push","swim","sit"],"o_pt":["empurrar","nadar","sentar"],"dica":"Os outros dois estão na lista do corpo.","dica_en":"The other two are on the body list.","ex":"Hand list: touch, lift, point, write, grab, push. Push is on it.","ex_pt":"Lista da mão: tocar, levantar, apontar, escrever, agarrar, empurrar. Empurrar está nela.","c":0},{"id":"f01","tema":"pushpull","tipo":"rapida","at":["F3"],"p":"Riding a bike. Is it a push or a pull?","p_pt":"Andar de bicicleta. É empurrar ou puxar?","o":["a push","a pull"],"o_pt":["empurrar","puxar"],"dica":"Os pés empurram os pedais para longe. Push = empurrar, pull = puxar.","dica_en":"The feet move the pedals away from the body.","ex":"In our lesson, riding a bike is a push: a force away from me.","ex_pt":"Na lição, andar de bicicleta é empurrar: uma força que afasta de mim.","img":"media/cie3/push-bike.jpg","c":0},{"id":"f02","tema":"pushpull","tipo":"rapida","at":["F3"],"p":"The boy moves the box. Is it a push or a pull?","p_pt":"O menino move a caixa. É um empurrão ou um puxão?","o":["a push","a pull"],"o_pt":["um empurrão","um puxão"],"dica":"Cuidado: push = empurrar, pull = puxar. O que a figura mostra?","dica_en":"Careful: push moves things away, pull brings them closer. What does the picture show?","ex":"The hands move the box away from the boy. That is a push.","ex_pt":"As mãos levam a caixa para longe do menino. É push, empurrar.","img":"media/cie3/push-box.jpg","c":0},{"id":"f03","tema":"pushpull","tipo":"rapida","at":["F3"],"p":"Is kicking a ball a push or a pull?","p_pt":"Chutar a bola é um empurrão ou um puxão?","o":["a push","a pull"],"o_pt":["um empurrão","um puxão"],"dica":"Cuidado: push = empurrar, pull = puxar. O que a figura mostra?","dica_en":"Careful: push moves things away, pull brings them closer. What does the picture show?","ex":"The foot moves the ball away from the boy. Kicking is a push.","ex_pt":"O pé leva a bola para longe do menino. Chutar é push, empurrar.","img":"media/cie3/push-ball.jpg","c":0},{"id":"f04","tema":"pushpull","tipo":"rapida","at":["F3"],"p":"A girl opens a door with her hands, moving it away from her. Is it a push or a pull?","p_pt":"Uma menina abre a porta com as mãos, levando-a para longe dela. É um empurrão ou um puxão?","o":["a push","a pull"],"o_pt":["um empurrão","um puxão"],"dica":"Para longe de mim: qual é a palavra? Push = empurrar, pull = puxar.","dica_en":"Away from me: which word is it?","ex":"The door moves away from the girl. That is a push.","ex_pt":"A porta vai para longe da menina. É push, empurrar.","c":0},{"id":"f05","tema":"pushpull","tipo":"rapida","at":["F4"],"p":"Two children play tug of war. Is it a push or a pull?","p_pt":"Duas crianças brincam de cabo de guerra. É um empurrão ou um puxão?","o":["a pull","a push"],"o_pt":["um puxão","um empurrão"],"dica":"Cuidado: push = empurrar, pull = puxar. O que a figura mostra?","dica_en":"Careful: push moves things away, pull brings them closer. What does the picture show?","ex":"Each child brings the rope closer. Tug of war is a pull.","ex_pt":"Cada criança traz a corda para perto. Cabo de guerra é pull, puxar.","img":"media/cie3/pull-rope.jpg","c":0},{"id":"f06","tema":"pushpull","tipo":"rapida","at":["F4"],"p":"The boy moves the wagon. Is it a push or a pull?","p_pt":"O menino move o carrinho. É um empurrão ou um puxão?","o":["a pull","a push"],"o_pt":["um puxão","um empurrão"],"dica":"Cuidado: push = empurrar, pull = puxar. O que a figura mostra?","dica_en":"Careful: push moves things away, pull brings them closer. What does the picture show?","ex":"The boy holds the handle and the wagon comes after him. That is a pull.","ex_pt":"O menino segura a alça e o carrinho vem atrás. É pull, puxar.","img":"media/cie3/pull-wagon.jpg","c":0},{"id":"f07","tema":"pushpull","tipo":"rapida","at":["F4"],"p":"The girl opens the drawer. Is it a push or a pull?","p_pt":"A menina abre a gaveta. É um empurrão ou um puxão?","o":["a pull","a push"],"o_pt":["um puxão","um empurrão"],"dica":"Cuidado: push = empurrar, pull = puxar. O que a figura mostra?","dica_en":"Careful: push moves things away, pull brings them closer. What does the picture show?","ex":"The drawer comes closer to the girl. Opening a drawer is a pull.","ex_pt":"A gaveta vem para perto da menina. Abrir gaveta é pull, puxar.","img":"media/cie3/pull-drawer.jpg","c":0},{"id":"f08","tema":"pushpull","tipo":"rapida","at":["F4"],"p":"The boy is fishing with a rod. Is it a push or a pull?","p_pt":"O menino pesca com uma vara. É um empurrão ou um puxão?","o":["a pull","a push"],"o_pt":["um puxão","um empurrão"],"dica":"Cuidado: push = empurrar, pull = puxar. O que a figura mostra?","dica_en":"Careful: push moves things away, pull brings them closer. What does the picture show?","ex":"The rod brings the fish closer to the boy. Fishing is a pull.","ex_pt":"A vara traz o peixe para perto do menino. Pescar é pull, puxar.","img":"media/cie3/pull-fish.jpg","c":0},{"id":"f10","tema":"pushpull","tipo":"rapida","at":["F1","F3"],"p":"The door says PUSH. Where does the door go?","p_pt":"A porta diz PUSH. Para onde a porta vai?","o":["away from her","closer to her"],"o_pt":["para longe dela","para perto dela"],"dica":"Atenção à palavra PUSH: push = empurrar, pull = puxar.","dica_en":"Think about the word PUSH on the door.","ex":"A push moves something away from me. The door goes away from the girl.","ex_pt":"Push é empurrar: leva algo para longe de mim. A porta vai para longe da menina.","img":"media/cie3/push-door.jpg","c":0},{"id":"f16","tema":"pushpull","tipo":"rapida","at":["F1"],"p":"A push is when I use a force to move something…","p_pt":"Empurrar é quando uso uma força para mover algo…","o":["away from me","closer to me"],"o_pt":["para longe de mim","para perto de mim"],"dica":"Cuidado: push parece \"puxar\", mas push = empurrar, pull = puxar.","dica_en":"Careful: think of pushing a heavy box.","ex":"A push moves something away from me.","ex_pt":"Empurrar move algo para longe de mim.","c":0},{"id":"f17","tema":"pushpull","tipo":"rapida","at":["F2"],"p":"A pull is when I use a force to move something…","p_pt":"Puxar é quando uso uma força para mover algo…","o":["closer to me","away from me"],"o_pt":["para perto de mim","para longe de mim"],"dica":"Lembre: push = empurrar, pull = puxar.","dica_en":"Think of opening a drawer.","ex":"A pull moves something closer to me.","ex_pt":"Puxar move algo para perto de mim.","c":0},{"id":"f18","tema":"pushpull","tipo":"conceito","at":["F1"],"p":"I use a force to move something away from me. It is…","p_pt":"Uso uma força para mover algo para longe de mim. É…","o":["a push","a pull"],"o_pt":["um empurrão","um puxão"],"dica":"Push = empurrar, pull = puxar. Qual leva para longe?","dica_en":"Think of a box going away from you. Which word is it?","ex":"Away from me is a push. Pushing a box moves it away.","ex_pt":"Para longe de mim é push, empurrar. Empurrar a caixa a leva para longe.","c":0},{"id":"f19","tema":"pushpull","tipo":"conceito","at":["F2"],"p":"I use a force to move something closer to me. It is…","p_pt":"Uso uma força para mover algo para perto de mim. É…","o":["a pull","a push"],"o_pt":["um puxão","um empurrão"],"dica":"Push = empurrar, pull = puxar. Qual traz para perto?","dica_en":"Think of a drawer coming to you. Which word is it?","ex":"Closer to me is a pull. Pulling a drawer brings it closer.","ex_pt":"Para perto de mim é pull, puxar. Puxar a gaveta a traz para perto.","c":0},{"id":"f21","tema":"pushpull","tipo":"conceito","at":["F5"],"p":"What are the two types of force?","p_pt":"Quais são os dois tipos de força?","o":["push and pull","up and down","slow and fast"],"o_pt":["empurrar e puxar","para cima e para baixo","devagar e rápido"],"dica":"Um leva para longe, o outro traz para perto.","dica_en":"One moves things away, the other brings them closer.","ex":"The two types of force are push and pull.","ex_pt":"Os dois tipos de força são push (empurrar) e pull (puxar).","c":0},{"id":"f24","tema":"pushpull","tipo":"rapida","at":["F6"],"p":"I move a shopping trolley away from me. Is it a push or a pull?","p_pt":"Levo o carrinho de compras para longe de mim. É um empurrão ou um puxão?","o":["a push","a pull"],"o_pt":["um empurrão","um puxão"],"dica":"Para longe de mim: push = empurrar, pull = puxar.","dica_en":"Away from me: which word is it?","ex":"The trolley moves away from me. That is a push.","ex_pt":"O carrinho vai para longe de mim. É push, empurrar.","c":0},{"id":"f29","tema":"pushpull","tipo":"rapida","at":["F7"],"p":"I pick a fruit from the plant. Is it a push or a pull?","p_pt":"Colho uma fruta da planta. É um empurrão ou um puxão?","o":["a pull","a push"],"o_pt":["um puxão","um empurrão"],"dica":"A fruta sai da planta e vem para sua mão. Push = empurrar, pull = puxar.","dica_en":"The fruit leaves the plant and comes to your hand.","ex":"I bring the fruit from the plant closer to me. That is a pull.","ex_pt":"Trago a fruta da planta para perto de mim. É pull, puxar.","c":0},{"id":"x06","tema":"directions","tipo":"conceito","at":["D3"],"p":"True or false: we might get lost if we run or don't pay attention.","p_pt":"Verdadeiro ou falso: podemos nos perder se corrermos ou não prestarmos atenção.","o":["True","False"],"o_pt":["Verdadeiro","Falso"],"dica":"Lembre do slide do mapa.","dica_en":"Remember the map slide.","ex":"True. On a map, pay attention to the details and the path, or you might get lost.","ex_pt":"Verdadeiro. No mapa, preste atenção nos detalhes e no caminho, ou você pode se perder.","c":0},{"id":"x08","tema":"position","tipo":"conceito","at":["A14"],"p":"Look at the words: behind, next to, in front of, over, in, on, between, under. There is a racket ___ the bag.","p_pt":"Olhe as palavras: atrás, ao lado, na frente, por cima, dentro, em cima, entre, embaixo. Tem uma raquete ___ a mochila.","o":["next to","over","between","behind","under"],"o_pt":["ao lado de","por cima de","entre","atrás de","embaixo de"],"dica":"Ache a raquete na sala.","dica_en":"Find the racket in the room.","ex":"The racket is right beside the bag: next to.","ex_pt":"A raquete está bem ao lado da mochila: ao lado de.","img":"media/cie3/room.jpg","c":0},{"id":"x09","tema":"position","tipo":"conceito","at":["A14"],"p":"Look at the words: behind, next to, in front of, over, in, on, between, under. There is a trophy ___ the books.","p_pt":"Olhe as palavras: atrás, ao lado, na frente, por cima, dentro, em cima, entre, embaixo. Tem um troféu ___ os livros.","o":["between","in","under","in front of","over"],"o_pt":["entre","dentro de","embaixo de","na frente de","por cima de"],"dica":"Olhe a prateleira.","dica_en":"Look at the shelf.","ex":"There are books on each side of the trophy: between.","ex_pt":"Há livros de cada lado do troféu: entre.","img":"media/cie3/room.jpg","c":0},{"id":"x10","tema":"position","tipo":"conceito","at":["A14"],"p":"Look at the words: behind, next to, in front of, over, in, on, between, under. There is a window ___ the sofa.","p_pt":"Olhe as palavras: atrás, ao lado, na frente, por cima, dentro, em cima, entre, embaixo. Tem uma janela ___ o sofá.","o":["behind","in front of","under","on","in"],"o_pt":["atrás de","na frente de","embaixo de","em cima de","dentro de"],"dica":"O sofá está mais perto de você.","dica_en":"The sofa is closer to you.","ex":"The sofa is in front and the window is at the back: behind.","ex_pt":"O sofá está na frente e a janela lá atrás: atrás de.","img":"media/cie3/room.jpg","c":0}];
function embaralha(a){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=a[i];a[i]=a[j];a[j]=t;}return a;}
return {TEMAS:TEMAS,ITENS:ITENS,POEMAS:{},doTema:function(k){return ITENS.filter(function(i){return i.tema===k;});},
sorteia:function(temas,n,tipo){if(typeof temas==='string')temas=[temas];var pool=ITENS.filter(function(i){return temas.indexOf(i.tema)>=0&&(!tipo||i.tipo===tipo);});return embaralha(pool).slice(0,n);}};})();
